const express = require('express');
const mysql = require('mysql2/promise');
const { authenticateManager } = require('../auth');

const app = express();
app.use(express.json());

let dbPool;
mysql.createPool(process.env.MYSQL_URI).then(p => { dbPool = p; });

app.post('/api/orgs/:orgId/sessions/revoke-user', authenticateManager, async (req, res) => {
  const { orgId } = req.params;
  const { targetUserId } = req.body;

  // Verify manager has administrative role in the specified organization
  if (req.user.organizationId !== orgId || req.user.role !== 'ORG_ADMIN') {
    return res.status(403).json({ error: 'Forbidden: not an administrator of this organization' });
  }

  // Ensure target user belongs to the same organization before revoking sessions
  const [userRows] = await dbPool.execute(
    'SELECT id FROM users WHERE id = ? AND organization_id = ?',
    [targetUserId, orgId]
  );

  if (userRows.length === 0) {
    return res.status(404).json({ error: 'Target user does not belong to your organization' });
  }

  const [result] = await dbPool.execute(
    "DELETE FROM sessions WHERE JSON_UNQUOTE(JSON_EXTRACT(data, '$.user.id')) = ? AND JSON_UNQUOTE(JSON_EXTRACT(data, '$.user.orgId')) = ?",
    [targetUserId, orgId]
  );

  res.json({ success: true, terminatedCount: result.affectedRows });
});

app.listen(8097);
